"""R11: decimales paso a paso. Contenido original con aritmética decimal exacta."""
import json
from decimal import Decimal as D
from pathlib import Path
U=[]
def fmt(x):
 s=format(D(x),'f')
 return (s.rstrip('0').rstrip('.') if '.' in s else s).replace('.',',')
def a(q,value,steps,wrong):
 opts=list(dict.fromkeys([str(value),*map(str,wrong)]));assert len(opts)>=2
 return dict(enunciado=q,respuesta_correcta=str(value),opciones=opts,paso_resuelto=steps,visual=None)
def unit(id,after,title,explanation,example,steps,hint,rows):
 assert len(rows)==6
 for i,r in enumerate(rows):
  r['id']=id+'-v'+str(i+1);k=i%len(r['opciones']);r['opciones']=r['opciones'][k:]+r['opciones'][:k]
 U.append(dict(id=id,tema='decimales_conversion',despues_de=after,titulo=title,explicacion=explanation,ejemplo=example,pasos=steps,pista=hint,visual=None,actividades=rows))
unit('prof_dec_milesimos','mat_dec_fraccion','Un lugar para cada parte','Después de la coma vienen décimos, centésimos y milésimos, en ese orden. Un milésimo es una de mil partes iguales de la unidad. Un cero guarda un lugar: 0,006 tiene seis milésimos, no seis décimos.','0,375 = 3 décimos + 7 centésimos + 5 milésimos.',['Contamos desde la coma: primer, segundo y tercer lugar.','La tercera cifra es 5; cuenta milésimos.'],'Contá los lugares desde la coma, también cuando aparece un cero.',[a(f'En {x}, ¿qué cifra ocupa el lugar de los milésimos?',x[-1],f'Después de la coma leemos {x.split(",")[1][0]}, {x.split(",")[1][1]} y {x[-1]}. El tercer lugar es el de los milésimos.',[x.split(',')[1][0],x.split(',')[1][1],'9']) for x in ['0,375','2,406','1,052','3,108','0,924','4,630']])
unit('prof_dec_ceros','prof_dec_milesimos','Ceros que conservan el valor','Podemos agregar o quitar ceros al final de la parte decimal sin cambiar la cantidad: tres décimos equivalen a treinta centésimos. Un cero entre la coma y otra cifra sí cambia su posición: 0,03 no es 0,3.','0,3 = 0,30 = 0,300.',['Tres décimos ocupan lo mismo que treinta centésimos.','Quitamos solo ceros finales: 0,300 vuelve a ser 0,3.'],'Quitá solo ceros al final de la parte decimal.',[a(f'¿Cuál de estas escrituras representa la misma cantidad que {x}?',right,f'Los ceros finales no cambian el valor: {x} = {right}.',[wrong,other]) for x,right,wrong,other in [('0,30','0,3','0,03','3'),('2,500','2,5','2,05','25'),('0,070','0,07','0,7','7'),('4,200','4,2','4,02','42'),('1,040','1,04','1,4','14'),('0,600','0,6','0,06','6')]])
unit('prof_dec_comparar','prof_dec_ceros','Comparar decimales lugar por lugar','Primero comparamos las partes enteras. Si son iguales, comparamos décimos, luego centésimos y después milésimos. Podemos completar con ceros al final. Tener más cifras no significa valer más.','0,8 es mayor que 0,75: 0,80 tiene 80 centésimos y 0,75 tiene 75.',['Escribimos 0,8 como 0,80 para comparar las mismas partes.','80 centésimos son más que 75 centésimos.'],'Igualá las posiciones con ceros finales y compará desde la izquierda.',[a(f'¿Qué número es mayor: {fmt(x)} o {fmt(y)}?',fmt(max(D(x),D(y))),f'Comparamos posiciones: {D(x):.3f} y {D(y):.3f}. El mayor es {fmt(max(D(x),D(y)))}.'.replace('.',','),[fmt(min(D(x),D(y))),'Son iguales']) for x,y in [('0.8','0.75'),('2.09','2.1'),('3.4','3.045'),('0.125','0.12'),('5.06','5.006'),('1.009','1.01')]])
unit('prof_dec_a_fraccion','prof_dec_comparar','Escribir el decimal como fracción','Contamos las cifras después de la coma. Una cifra indica décimos y denominador 10; dos indican centésimos y denominador 100; tres indican milésimos y denominador 1000. El numerador es el número escrito sin coma.','1,25 = 125/100.',['Hay dos cifras decimales: usamos denominador 100.','Sin la coma queda 125; escribimos 125/100.'],'El denominador tiene tantos ceros como cifras decimales.',[a(f'Escribí {x.replace(".",",")} como fracción con denominador {10**len(x.split(".")[1])}, sin simplificar.',f'{int(D(x)*10**len(x.split(".")[1]))}/{10**len(x.split(".")[1])}',f'Hay {len(x.split(".")[1])} cifras decimales. El numerador es {int(D(x)*10**len(x.split(".")[1]))} y el denominador es {10**len(x.split(".")[1])}.',[f'{int(D(x)*10**len(x.split(".")[1]))}/{10**(len(x.split(".")[1])+1)}',f'{int(D(x)*10**len(x.split(".")[1]))+1}/{10**len(x.split(".")[1])}']) for x in ['1.25','0.6','0.075','2.04','3.125','0.08']])
unit('prof_dec_desde_fraccion','prof_dec_a_fraccion','Dividir para pasar a decimal','Una fracción también indica una división: numerador dividido por denominador. Si queda resto, podemos continuar con décimos y centésimos. Si el resto llega a cero, el decimal es exacto. Hay otras fracciones cuyo decimal no termina.','3/4 = 3 ÷ 4 = 0,75.',['3 es menor que 4: anotamos 0 enteros y la coma. 30 décimos entre 4 dan 7 décimos y sobran 2.','Esos 2 décimos son 20 centésimos: entre 4 dan 5 centésimos. Queda 0,75 y resto cero.'],'Dividí el numerador por el denominador; si hay resto, seguí con partes diez veces menores.',[a(f'Convertí {n}/{d} en un decimal exacto.',fmt(D(n)/D(d)),f'{n} ÷ {d} = {fmt(D(n)/D(d))}. Comprobamos: {fmt(D(n)/D(d))} × {d} = {n}.',[fmt(D(n)/D(d)*10),fmt(D(n)/D(d)/10)]) for n,d in [(3,4),(1,2),(7,4),(3,8),(9,5),(7,20)]])
unit('prof_dec_sumar_distintas','mat_dec_sumar','Sumar décimos y centésimos','Para sumar números con distinta cantidad de cifras decimales, alineamos las comas y completamos con ceros finales. Después sumamos partes del mismo tamaño. Cada cien centésimos forman una unidad.','2,35 + 0,8 = 2,35 + 0,80 = 3,15.',['Son 235 centésimos más 80 centésimos: 315 centésimos.','300 centésimos forman 3 unidades y quedan 15 centésimos: 3,15.'],'Sumá partes del mismo tamaño; diez centésimos forman un décimo.',[a(f'Resolvé {fmt(x)} + {fmt(y)}.',fmt(D(x)+D(y)),f'En centésimos: {int(D(x)*100)} + {int(D(y)*100)} = {int((D(x)+D(y))*100)}. Volvemos a escribir el resultado: {fmt(D(x)+D(y))}.',[fmt(D(x)+D(y)+D('.1')),fmt((D(x)+D(y))/10)]) for x,y in [('2.35','.8'),('1.08','.7'),('4.6','.75'),('3.09','1.2'),('.85','.4'),('5.07','2.9')]])
unit('prof_dec_restar_reagrupar','mat_dec_restar','Restar cuando necesitamos cambiar una unidad','Al restar, alineamos las comas y completamos con ceros finales. Podemos cambiar una unidad por cien centésimos sin cambiar el total. Así tenemos partes pequeñas para quitar.','5 − 1,75 = 5,00 − 1,75 = 3,25.',['Reescribimos 5 unidades como 4 unidades y 100 centésimos.','Quitamos 1 unidad y 75 centésimos: quedan 3 unidades y 25 centésimos.'],'Podés cambiar una unidad por cien centésimos y conservar el total.',[a(f'Resolvé {fmt(x)} − {fmt(y)}.',fmt(D(x)-D(y)),f'En centésimos: {int(D(x)*100)} − {int(D(y)*100)} = {int((D(x)-D(y))*100)}. Quedan {fmt(D(x)-D(y))}.',[fmt(D(x)-D(y)+D('.1')),fmt(D(x)+D(y))]) for x,y in [('5','1.75'),('4.2','.85'),('6','2.08'),('3.5','1.76'),('7.1','3.25'),('2','.65')]])
unit('prof_dec_escalar','prof_dec_restar_reagrupar','Diez veces más, diez veces menos','Multiplicar por 10 hace que cada cifra valga diez veces más; dividir por 10 hace que valga diez veces menos. Con 100 son dos cambios de posición y con 1000 son tres. Agregar ceros al final del decimal no multiplica su valor.','0,45 × 10 = 4,5; 4,5 ÷ 10 = 0,45.',['Al multiplicar por 10, 45 centésimos se convierten en 45 décimos.','Al dividir por 10 hacemos el cambio inverso: 45 décimos pasan a ser 45 centésimos.'],'Pensá primero si el resultado debe ser mayor o menor; después contá los cambios de posición.',[a(f'Resolvé {fmt(x)} {op} {k}.',fmt(D(x)*k if op=='×' else D(x)/k),f'Cada cifra cambia {len(str(k))-1} lugar(es) hacia un valor '+('mayor' if op=='×' else 'menor')+f'. Resultado: {fmt(D(x)*k if op=="×" else D(x)/k)}.',[fmt(D(x)/k if op=='×' else D(x)*k),fmt(x)]) for x,op,k in [('.45','×',10),('2.07','×',100),('.006','×',1000),('4.5','÷',10),('7','÷',100),('65','÷',1000)]])
unit('prof_dec_producto','mat_dec_producto','Multiplicar dos cantidades decimales','Para multiplicar decimales, multiplicamos como si no hubiera comas y luego contamos las cifras decimales de ambos factores. El producto lleva esa cantidad total de posiciones decimales; si faltan cifras, completamos con ceros a la izquierda. Multiplicar por una cantidad entre 0 y 1 toma solo una parte.','1,2 × 0,3 = 0,36.',['12 × 3 = 36. Cada factor tiene una cifra decimal: son dos en total.','36 centésimos se escriben 0,36. Tomar tres décimos de 1,2 da menos que 1,2.'],'Sumá las posiciones decimales de los dos factores.',[a(f'Resolvé {fmt(x)} × {fmt(y)}.',fmt(D(x)*D(y)),f'Multiplicamos sin comas y contamos {len(x.split(".")[1])+len(y.split(".")[1])} posiciones decimales en total. El resultado es {fmt(D(x)*D(y))}.',[fmt(D(x)*D(y)*10),fmt(D(x)+D(y))]) for x,y in [('1.2','0.3'),('0.4','0.2'),('2.5','1.2'),('0.06','0.5'),('1.25','0.4'),('3.2','0.25')]])
unit('prof_dec_dividir_natural','mat_dec_dividir','Repartir también los centésimos','Podemos repartir una cantidad decimal convirtiéndola a centésimos. Dividimos esos centésimos entre la cantidad de grupos y escribimos de nuevo el decimal. Si quedan partes por repartir, seguimos con una unidad más pequeña.','4,5 litros entre 6 botellas: 0,75 litros en cada una.',['4,5 litros equivalen a 450 centésimos de litro.','450 ÷ 6 = 75 centésimos por botella: 0,75 litros.'],'Convertí a partes pequeñas del mismo tamaño antes de repartir.',[a(f'Resolvé {fmt(x)} ÷ {n}.',fmt(D(x)/n),f'{fmt(x)} equivale a {int(D(x)*100)} centésimos. {int(D(x)*100)} ÷ {n} = {int(D(x)*100/n)} centésimos: {fmt(D(x)/n)}.',[fmt(D(x)/n*10),fmt(D(x)/n/10)]) for x,n in [('4.5',6),('3.6',8),('7.2',5),('1.8',4),('6.3',9),('2.5',2)]])
unit('prof_dec_dividir_decimal','prof_dec_dividir_natural','Dividir por una cantidad decimal','Una división conserva su resultado si multiplicamos dividendo y divisor por el mismo número distinto de cero. Podemos multiplicar ambos por 10 o por 100 para quitar la coma del divisor. Nunca cambiamos solo uno.','1,5 ÷ 0,3 = 15 ÷ 3 = 5.',['Multiplicamos ambos números por 10: 1,5 pasa a 15 y 0,3 pasa a 3.','15 ÷ 3 = 5. Comprobamos: 5 × 0,3 = 1,5.'],'Multiplicá los dos números por el mismo factor hasta que el divisor sea entero.',[a(f'Resolvé {fmt(x)} ÷ {fmt(y)}.',fmt(D(x)/D(y)),f'Multiplicamos ambos por {10**len(y.split(".")[1])}: {fmt(D(x)*10**len(y.split(".")[1]))} ÷ {fmt(D(y)*10**len(y.split(".")[1]))}. Resultado: {fmt(D(x)/D(y))}.',[fmt(D(x)/D(y)/10),fmt(D(x)*D(y))]) for x,y in [('1.5','0.3'),('2.4','0.6'),('1.8','0.12'),('0.75','0.25'),('3.6','1.2'),('2.5','0.5')]])
unit('prof_dec_dos_pasos','prof_dec_dividir_decimal','Un problema, dos cuentas pequeñas','En un problema podemos encontrar un resultado intermedio antes de responder. Primero anotamos qué necesitamos averiguar y después usamos ese resultado en la siguiente cuenta. Al final comprobamos si tiene sentido.','Tenés 10 pesos de juego. Comprás dos fichas de 2,35 pesos cada una. Te quedan 5,30 pesos.',['Las dos fichas cuestan 2 × 2,35 = 4,70 pesos.','Restamos el gasto al dinero inicial: 10 − 4,70 = 5,30 pesos.'],'Primero calculá el gasto total; después restalo del dinero inicial.',[a(f'En una tienda de juego tenés {fmt(total)} pesos. Comprás {n} fichas de {fmt(price)} pesos cada una. ¿Cuántos pesos te quedan?',fmt(D(total)-n*D(price)),f'Gasto: {n} × {fmt(price)} = {fmt(n*D(price))}. Después: {fmt(total)} − {fmt(n*D(price))} = {fmt(D(total)-n*D(price))} pesos.',[fmt(D(total)-D(price)),fmt(n*D(price))]) for total,n,price in [('10',2,'2.35'),('8',3,'1.2'),('12',4,'2.15'),('5',2,'1.75'),('15',3,'2.4'),('20',4,'3.25')]])
# Procedimientos completos para el segundo intento: no repetir únicamente el resultado.
for u in U:
 if u['id']=='prof_dec_desde_fraccion':
  import re
  for row in u['actividades']:
   n,d=map(int,re.search(r'(\d+)/(\d+)',row['enunciado']).groups());integer,remainder=divmod(n,d)
   steps=[f'{n} ÷ {d}: {integer} entero(s), resto {remainder}.']
   for label in ['décimos','centésimos','milésimos']:
    if not remainder:break
    amount=remainder*10;digit,remainder=divmod(amount,d)
    steps.append(f'{amount} {label} entre {d}: {digit} {label}, resto {remainder} {label}.')
   assert remainder==0
   steps.append('Juntamos los lugares: '+row['respuesta_correcta']+'.')
   row['paso_resuelto']='\n'.join(steps)
 if u['id']=='prof_dec_producto':
  import re
  for row in u['actividades']:
   left,right=re.findall(r'\d+,\d+',row['enunciado']);x=int(left.replace(',',''));y=int(right.replace(',',''));places=len(left.split(',')[1])+len(right.split(',')[1])
   row['paso_resuelto']=f'Sin comas: {x} × {y} = {x*y}.\nLos factores tienen {len(left.split(",")[1])} y {len(right.split(",")[1])} cifra(s) decimal(es): {places} en total.\nColocamos la coma contando {places} lugares desde la derecha: {row["respuesta_correcta"]}.'

root=Path(__file__).resolve().parents[1];p=root/'src/lib/contenido-bases.js';s=p.read_text(encoding='utf-8')
start='// R11: decimales paso a paso.';end='// FIN R11'
if start in s:s=s[:s.index(start)]+s[s.index(end)+len(end):]
code=start+'\nconst DECIMALES_R11 = '+json.dumps(U,ensure_ascii=False,indent=2)+''';
for (const unidad of DECIMALES_R11) {
 const indice = UNIDADES_BASES.findIndex(u => u.id === unidad.despues_de);
 if (indice < 0) throw new Error('Falta el paso anterior de ' + unidad.id);
 UNIDADES_BASES.splice(indice + 1, 0, unidad);
}
'''+end+'\n\n'
i=s.index('export const TEMAS_BASES');p.write_text(s[:i]+code+s[i:],encoding='utf-8')
print(len(U),'unidades nuevas;',sum(len(u['actividades']) for u in U),'actividades')
